import json
import urllib.request

# Try to discover what the arc-proxy supports
base_url = 'http://127.0.0.1:34799/v1'
api_key = 'arc-proxy'

# List what's available at the root level
try:
    req = urllib.request.Request(base_url, headers={
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    })
    resp = urllib.request.urlopen(req, timeout=3)
    print(f"Root endpoint: {resp.read()}")
except Exception as e:
    print(f"Root error: {e}")

# Check for eval-related endpoints  
endpoints = [
    '/tasks', '/evaluations', '/evaluate', '/submit', 
    '/v1/evaluate', '/v1/submit', '/task', '/challenge'
]

print("\n=== Checking eval-specific endpoints ===")
for ep in endpoints:
    full_ep = base_url + ep
    try:
        req = urllib.request.Request(full_ep, headers={
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json'
        })
        resp = urllib.request.urlopen(req, timeout=5)
        data = json.loads(resp.read())
